<div class="mb-4"><h1 class="h3"><?= $ticket ? 'Edit ticket' : 'Create a ticket' ?></h1><p class="text-secondary">Describe the issue and choose the closest category.</p></div><div class="card"><div class="card-body"><form method="post" action="<?= $ticket ? site_url('tickets/' . $ticket['id'] . '/edit') : site_url('tickets') ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label" for="subject">Subject</label><input class="form-control" id="subject" name="subject" maxlength="180" required value="<?= esc(old('subject', $ticket['subject'] ?? '')) ?>"></div><div class="mb-3"><label class="form-label" for="description">Description</label><textarea class="form-control" id="description" name="description" rows="6" maxlength="10000" required><?= esc(old('description', $ticket['description'] ?? '')) ?></textarea></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label" for="category_id">Category</label><select class="form-select" id="category_id" name="category_id" required><option value="">Choose…</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (string) old('category_id', $ticket['category_id'] ?? '') === (string) $category['id'] ? 'selected' : '' ?>><?= esc($category['name']) ?></option><?php endforeach ?></select></div><div class="col-md-6 mb-3"><label class="form-label" for="priority">Priority</label><select class="form-select" id="priority" name="priority" required><?php foreach (['Low', 'Medium', 'High'] as $priority): ?><option <?= old('priority', $ticket['priority'] ?? 'Medium') === $priority ? 'selected' : '' ?>><?= esc($priority) ?></option><?php endforeach ?></select></div></div><button class="btn btn-primary">Save</button> <a class="btn btn-outline-secondary" href="<?= site_url('tickets') ?>">Cancel</a></form></div></div>
